 function dimensions(shape){return {h:Math.max(...shape.map(c=>c[0]))+1,w:Math.max(...shape.map(c=>c[1]))+1}}
 function canPlace(shape,row,col,b=state.board){return shape.every(([y,x])=>row+y>=0&&row+y<9&&col+x>=0&&col+x<9&&!b[(row+y)*9+col+x])}
 function canFitAny(shapes,b=state.board){return shapes.some(s=>{for(let r=0;r<9;r++)for(let c=0;c<9;c++)if(canPlace(s,r,c,b))return true;return false})}
 function makeSet(){let candidates=[];for(let attempt=0;attempt<35;attempt++){let inds=[rand(SHAPES.length),rand(SHAPES.length),rand(SHAPES.length)],set=inds.map(i=>i);if(canFitAny(set.map(i=>SHAPES[i]))){candidates=set;break}if(!candidates.length)candidates=set}return candidates.map(i=>({id:i,color:COLORS[rand(COLORS.length)]}))}
