 else if(kind==='stats'){let cleared=data.stats.cleared+state.cleared;d.innerHTML=`<div class="dialog-kicker">ВАШ ПУТЬ</div><h2>Статистика</h2><p>Каждый ход — маленькая победа.</p><div class="stat-grid"><div class="stat-card"><strong>${data.stats.games}</strong><span>ЗАВЕРШЁННЫХ ПАРТИЙ</span></div><div class="stat-card"><strong>${cleared}</strong><span>ОЧИЩЕНО КЛЕТОК</span></div><div class="stat-card"><strong>×${Math.max(data.stats.maxCombo,state.maxCombo)}</strong><span>ЛУЧШАЯ СЕРИЯ</span></div><div class="stat-card"><strong>${data.best.classic||0}</strong><span>РЕКОРД КЛАССИКИ</span></div></div><div class="setting-row"><span>Задание дня</span><span style="color:var(--lime);font-size:11px">${DAILY_TEXT[Number(today().slice(-2))%3]}</span></div><div class="dialog-actions" style="margin-top:14px"><button class="secondary-btn" data-action="close">Закрыть</button></div>`}
 $('#overlay').classList.add('open');}
function closeDialog(){ $('#overlay').classList.remove('open');if(state.paused){state.paused=false;if(mode==='timed')startClock();persist()} }
function pause(){if(state.over)return;state.paused=true;clearInterval(timerHandle);showDialog('pause');persist()}
$('#dialog').addEventListener('click',e=>{let action=e.target.closest('[data-action]')?.dataset.action;if(action==='close'){closeDialog()}else if(action==='resume'){state.paused=false;$('#overlay').classList.remove('open');if(mode==='timed')startClock();persist()}else if(action==='restart'){ $('#overlay').classList.remove('open');newGame(mode)}let setting=e.target.closest('[data-setting]')?.dataset.setting;if(setting){settings[setting]=!settings[setting];data.settings=settings;persist();showDialog('settings')}});
$('#overlay').addEventListener('click',e=>{if(e.target===$('#overlay')&& !state.paused)closeDialog()});
$('#settingsBtn').addEventListener('click',()=>showDialog('settings'));$('#statsBtn').addEventListener('click',()=>showDialog('stats'));$('#pauseBtn').addEventListener('click',pause);
document.querySelectorAll('.mode-tab').forEach(b=>b.addEventListener('click',()=>{if(b.dataset.mode===mode)return;newGame(b.dataset.mode)}));
trayEl.addEventListener('pointerdown',e=>{let slot=e.target.closest('.piece-slot');if(!slot||!state.pieces[Number(slot.dataset.slot)]||state.over)return;let i=Number(slot.dataset.slot);state.selected=i;drag={i,startX:e.clientX,startY:e.clientY,moved:false};slot.setPointerCapture?.(e.pointerId);renderTray();e.preventDefault()});
document.addEventListener('pointermove',e=>{if(drag){if(Math.hypot(e.clientX-drag.startX,e.clientY-drag.startY)>7)drag.moved=true;if(drag.moved){let p=state.pieces[drag.i];if(p){let ghost=document.querySelector('.drag-ghost');if(!ghost){ghost=document.createElement('div');ghost.className='drag-ghost';document.body.append(ghost);let s=SHAPES[p.id],d=dimensions(s);ghost.style.gridTemplateColumns=`repeat(${d.w},16px)`;ghost.style.display='grid';ghost.style.gap='3px';for(let y=0;y<d.h;y++)for(let x=0;x<d.w;x++){let q=document.createElement('i');q.className='piece-cell'+(s.some(([a,b])=>a===y&&b===x)?'':' off');q.style.setProperty('--piece-color',p.color);ghost.append(q)}}ghost.style.left=e.clientX+'px';ghost.style.top=e.clientY+'px';setPreviewFromPoint(e.clientX,e.clientY)}}}else if(state.selected>=0){setPreviewFromPoint(e.clientX,e.clientY)}});
document.addEventListener('pointerup',e=>{if(!drag)return;let wasDrag=drag.moved,index=document.elementFromPoint(e.clientX,e.clientY)?.closest('.cell')?.dataset.index;document.querySelector('.drag-ghost')?.remove();drag=null;if(wasDrag&&index!==undefined){let p=state.pieces[state.selected],d=dimensions(SHAPES[p.id]),i=Number(index),r=Math.floor(i/9)-Math.floor((d.h-1)/2),c=i%9-Math.floor((d.w-1)/2);preview={r,c};place(i)}else if(!wasDrag){if(state.selected===undefined)state.selected=-1;renderTray();updateHUD()}else{preview=null;refreshPreview()}});
boardEl.addEventListener('pointermove',e=>{if(state.selected>=0&&!drag){let cell=e.target.closest('.cell');if(cell)setPreviewFromPoint(e.clientX,e.clientY)}});
boardEl.addEventListener('pointerleave',()=>{if(!drag){preview=null;refreshPreview()}});
boardEl.addEventListener('click',e=>{let cell=e.target.closest('.cell');if(cell)place(Number(cell.dataset.index))});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if($('#overlay').classList.contains('open'))closeDialog();else pause()}if(e.key>='1'&&e.key<='3'){let i=Number(e.key)-1;if(state.pieces[i]){state.selected=i;renderTray();updateHUD()}}});
let savedMode='classic';try{let saved=JSON.parse(localStorage.getItem('mosaic-current')||'null');if(saved?.mode)savedMode=saved.mode}catch{}newGame(savedMode,true);
})();
</script>
</body>
</html>

